-- Generated by `elody-ui analytics generate` from vlacc.analytics.ttl; do not edit.
-- One row per entity; a reload inserts a newer version, ReplacingMergeTree keeps the latest (read with FINAL).
CREATE DATABASE IF NOT EXISTS raw;

CREATE TABLE IF NOT EXISTS raw.vlacc_entities
(
    id                          String,
    type                        LowCardinality(String) COMMENT 'type',
    created_at                  Nullable(DateTime64(3, 'Europe/Brussels')) COMMENT 'audit.created.at',
    created_by                  String COMMENT 'audit.created.by',
    updated_at                  DateTime64(3, 'Europe/Brussels') COMMENT 'audit.updated.at',
    updated_by                  String COMMENT 'audit.updated.by',
    audience_type               LowCardinality(String) COMMENT 'properties.audience_type.value',
    avi_read_level_code         Array(LowCardinality(String)) COMMENT 'properties.avi_read_level_code.value',
    bibliographic_type          LowCardinality(String) COMMENT 'properties.bibliographic_type.value',
    genre_type                  Array(LowCardinality(String)) COMMENT 'properties.genre_type.value',
    source_id_online_collection Array(LowCardinality(String)) COMMENT 'properties.id_online_collection_group.value.source_id_online_collection',
    land_or_language            LowCardinality(String) COMMENT 'properties.land_or_language.value',
    level                       LowCardinality(String) COMMENT 'properties.level.value',
    life_dates                  LowCardinality(String) COMMENT 'properties.life_dates.value',
    literary_type               LowCardinality(String) COMMENT 'properties.literary_type.value',
    material_type               LowCardinality(String) COMMENT 'properties.material_type.value',
    publication_year            LowCardinality(String) COMMENT 'properties.publication_year.value',
    record_format               LowCardinality(String) COMMENT 'properties.record_format.value',
    record_type                 LowCardinality(String) COMMENT 'properties.record_type.value',
    status_field                LowCardinality(String) COMMENT 'properties.status_field.value',
    target_audience             LowCardinality(String) COMMENT 'properties.target_audience.value',
    ingested_at                 DateTime DEFAULT now()
)
ENGINE = ReplacingMergeTree(updated_at)
ORDER BY (type, id);
